// Turns the "boards" list from "Configure me" into one API URL per company. An empty list is fine.
// Each line: name, ats, slug. ats is ashby, greenhouse or lever. The slug is the last part of the board URL:
//   jobs.ashbyhq.com/<slug>   boards.greenhouse.io/<slug>   jobs.lever.co/<slug>
const cfg = $('Configure me').first().json;
const url = {
  ashby: s => `https://api.ashbyhq.com/posting-api/job-board/${s}`,
  greenhouse: s => `https://boards-api.greenhouse.io/v1/boards/${s}/jobs?content=true`,
  lever: s => `https://api.lever.co/v0/postings/${s}?mode=json`,
};
const out = [];
for (const line of String(cfg.boards || '').split('\n')) {
  const [company, ats, slug] = line.split(',').map(x => (x || '').trim());
  if (!company || line.trim().startsWith('#')) continue;
  const a = (ats || '').toLowerCase();
  if (!url[a] || !slug) throw new Error(`Bad board line: "${line}". Expected: name, ashby|greenhouse|lever, slug`);
  out.push({ json: { company, ats: a, url: url[a](slug) } });
}
return out;

// One shape for every ATS and feed: {company, title, location, remote, url, source, description}.
const boards = $('Boards to watch').all();
const clean = s => String(s || '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const out = [];
$input.all().forEach((item, i) => {
  const { company, ats } = boards[i].json;
  const body = item.json.body;
  if (!body || item.json.statusCode >= 400) return;          // board down: skip, don't fail the run
  let jobs = [];
  if (ats === 'ashby') jobs = (body.jobs || []).map(j => ({
    title: j.title, url: j.jobUrl, text: j.descriptionPlain,
    location: [j.location, ...(j.secondaryLocations || []).map(s => s.location)].filter(Boolean).join(' / '),
    remote: j.isRemote === true || /remote/i.test(j.workplaceType || '') }));
  if (ats === 'greenhouse') jobs = (body.jobs || []).map(j => ({
    title: j.title, url: j.absolute_url, text: j.content,
    location: (j.location || {}).name || '', remote: /remote/i.test((j.location || {}).name || '') }));
  if (ats === 'lever') jobs = (Array.isArray(body) ? body : []).map(j => ({
    title: j.text, url: j.hostedUrl, text: j.descriptionPlain,
    location: (j.categories || {}).location || '', remote: /remote/i.test(j.workplaceType || '') }));
  for (const j of jobs) {
    const text = clean(j.text);
    out.push({ json: {
      company, title: (j.title || '').trim(), location: j.location, remote: j.remote, url: j.url, source: ats,
      description_snippet: text.slice(0, 280),
      description: text.slice(0, 3500),
      // Identity of an opening = company + normalized title (URLs get re-issued, feeds repeat boards).
      key: `${norm(company)}|${norm(j.title)}`,
    } });
  }
});
return out;

