// Attach the verdict to each posting. A failed LLM call delivers the posting unjudged, never drops it.
const src = $('Cap per run').all();
const minScore = Number($('Configure me').first().json.minScore) || 6;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
return $input.all().map((item, i) => {
  const p = src[i].json;
  const v = item.json.output;
  const judged = !!(v && typeof v.fit === 'boolean');
  const score = judged ? Math.max(1, Math.min(10, Number(v.score) || 1)) : null;
  const deliver = judged ? (v.fit && score >= minScore) : true;
  const head = judged ? `<b>${score}/10</b>` : '<b>unjudged</b>';
  const reason = judged ? v.reason : `no verdict (${esc(item.json.error || 'LLM failed')})`;
  const where = [p.location || 'location n/a', p.remote ? 'remote' : ''].filter(Boolean).join(' · ');
  // Feed postings name and link their source, as Jobicy and Himalayas require.
  const via = p.via ? ` · via <a href="${esc(p.url)}">${esc(p.via)}</a>` : '';
  const card = `${head} · <a href="${esc(p.url)}">${esc(p.title)}</a>\n${esc(p.company)} · ${esc(where)}${via}\n<i>${esc(reason)}</i>`;
  return { json: { ...p, judged, fit: judged ? v.fit : null, score, reason, deliver, card } };
});

// One header line per run, sent before the cards.
const n = name => $(name).all().length;
const items = $input.all().map(i => i.json);
const fetched = $('Merge sources').all();
const fromFeeds = fetched.filter(i => i.json.via).length;
const fits = items.filter(j => j.judged && j.deliver).length;
const unjudged = items.filter(j => !j.judged).length;
const day = $now.toFormat('ccc d LLL');
const parts = [
  fits ? `<b>${fits} role${fits === 1 ? '' : 's'} fit</b>` : 'nothing fits the profile',
  `${fetched.length} fetched (${fetched.length - fromFeeds} boards, ${fromFeeds} feeds)`,
  `${n('Role and location filter')} match your role`,
  `${n('New since last run')} new`,
  `${items.length} judged`,
];
if (unjudged) parts.push(`${unjudged} unjudged`);
return [{ json: { text: `<b>Job monitor · ${day}</b>\n` + parts.join(' · ') } }];

// Marks each posting with inRegion: can the candidate work from where this job is?
// "allowedRegion" in "Configure me" names one entry of REGIONS below; "any" switches the check off.
//   kept:     the location names your region, or says worldwide / anywhere / global
//   dropped:  the location names only other regions (e.g. "North America", "Remote, US")
//   passed:   empty or unclear locations such as "Remote" go on to the LLM, which reads the posting
// Each region is one case-insensitive, whole-word pattern. Edit a list, or add your own region.
// Ambiguous names (Georgia: country or US state?) are left out on purpose.
const REGIONS = {
  'Europe': /\b(europe|european union|eu|eea|emea|dach|nordics|benelux|uk|united kingdom|great britain|britain|england|scotland|wales|ireland|germany|france|spain|portugal|italy|netherlands|belgium|luxembourg|switzerland|austria|poland|czech republic|czechia|slovakia|hungary|romania|bulgaria|greece|croatia|slovenia|serbia|bosnia|montenegro|albania|kosovo|north macedonia|moldova|ukraine|estonia|latvia|lithuania|finland|sweden|norway|denmark|iceland|malta|cyprus|turkey|london|manchester|edinburgh|dublin|berlin|munich|hamburg|frankfurt|cologne|paris|lyon|madrid|barcelona|valencia|lisbon|porto|milan|rome|amsterdam|rotterdam|brussels|zurich|geneva|vienna|warsaw|krakow|wroclaw|prague|budapest|bucharest|sofia|athens|zagreb|belgrade|tallinn|riga|vilnius|helsinki|stockholm|oslo|copenhagen)\b/i,
  'North America': /\b(north america|americas|amer|us|usa|u\.s|united states|canada|new york|nyc|san francisco|bay area|los angeles|seattle|austin|boston|chicago|denver|atlanta|miami|dallas|houston|washington|california|texas|florida|massachusetts|virginia|colorado|new jersey|pennsylvania|illinois|toronto|vancouver|montreal|ottawa)\b/i,
  'Latin America': /\b(latam|latin america|south america|americas|amer|mexico|brazil|argentina|colombia|chile|peru|uruguay|costa rica|sao paulo|são paulo|buenos aires|bogota|santiago)\b/i,
  'Asia Pacific': /\b(apac|asia|australia|new zealand|india|japan|singapore|korea|china|hong kong|taiwan|indonesia|philippines|vietnam|thailand|malaysia|tokyo|seoul|sydney|melbourne|auckland|bangalore|bengaluru|hyderabad|mumbai|pune|delhi|shanghai|beijing|jakarta|manila|ho chi minh|hanoi|bangkok|kuala lumpur)\b/i,
  'Middle East and Africa': /\b(emea|mena|middle east|africa|israel|tel aviv|uae|united arab emirates|dubai|abu dhabi|saudi arabia|ksa|riyadh|qatar|doha|egypt|cairo|south africa|cape town|johannesburg|nigeria|lagos|kenya|nairobi)\b/i,
};
const WORLDWIDE = /\b(worldwide|anywhere|global|globally)\b/i;

const want = String($('Configure me').first().json.allowedRegion || 'any').trim();
const mine = Object.keys(REGIONS).find(name => name.toLowerCase() === want.toLowerCase());
if (want.toLowerCase() !== 'any' && !mine) {
  throw new Error(`allowedRegion "${want}" is not in REGIONS of the "Region check" node. Use one of: ${Object.keys(REGIONS).join(', ')}, or any.`);
}
const others = Object.keys(REGIONS).filter(name => name !== mine).map(name => REGIONS[name]);
return $input.all().map(item => {
  const loc = String(item.json.location || '');
  item.json.inRegion = !mine || WORLDWIDE.test(loc) || REGIONS[mine].test(loc) || !others.some(re => re.test(loc));
  return item;
});

// Stops early when a setting is missing, so the run does not fail halfway.
const cfg = $input.first().json;
if (/^YOUR_/.test(String(cfg.telegramChatId || 'YOUR_'))) {
  throw new Error('Set telegramChatId in the "Configure me" node before running.');
}
const hasBoards = String(cfg.boards || '').split('\n').some(l => l.trim() && !l.trim().startsWith('#'));
if (!hasBoards && cfg.useAggregators !== true) {
  throw new Error('Nothing to read: the boards list in "Configure me" is empty and useAggregators is off. Add a company or turn useAggregators on.');
}
return [{ json: cfg }];

// Turns "Configure me" into the aggregator feed URLs to read. Both feeds are free, public and need no key.
// Their terms ask you to link to the listing on their site and name them as the source.
// The job card does both, so keep the "via" link in "Apply verdict" if you edit it.
//   Jobicy     https://jobicy.com/jobs-rss-feed   poll at most once per hour
//   Himalayas  https://himalayas.app/api          20 jobs per page
// To drop a feed, delete its block below.
const cfg = $('Configure me').first().json;
if (cfg.useAggregators !== true) return [];
const q = encodeURIComponent(String(cfg.feedKeywords || '').trim());
// Jobicy can pre-filter by region. Region check still runs on every posting.
const JOBICY_GEO = { 'europe': 'europe', 'latin america': 'latam', 'asia pacific': 'apac', 'middle east and africa': 'emea' };
const geo = JOBICY_GEO[String(cfg.allowedRegion || '').trim().toLowerCase()];
const out = [];
// Jobicy: the 100 newest matches.
out.push({ json: { source: 'Jobicy', url: `https://jobicy.com/api/v2/remote-jobs?count=100${q ? `&tag=${q}` : ''}${geo ? `&geo=${geo}` : ''}` } });
// Himalayas: the 3 newest pages of keyword search results.
for (const page of [1, 2, 3]) {
  out.push({ json: { source: 'Himalayas', url: `https://himalayas.app/jobs/api/search?sort=recent${q ? `&q=${q}` : ''}&page=${page}` } });
}
return out;

// Same shape as the board branch. url stays the listing page on the feed's own site, as its terms ask.
const feeds = $('Feeds to read').all();
const clean = s => String(s || '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const out = [];
$input.all().forEach((item, i) => {
  const { source } = feeds[i].json;
  const body = item.json.body;
  if (!body || item.json.statusCode >= 400) return;          // feed down: skip, don't fail the run
  let jobs = [];
  if (source === 'Jobicy') jobs = (body.jobs || []).map(j => ({
    company: j.companyName, title: j.jobTitle, url: j.url, text: j.jobDescription,
    location: String(j.jobGeo || '').split(',').map(s => s.trim()).filter(Boolean).join(', ') }));
  if (source === 'Himalayas') jobs = (body.jobs || []).map(j => ({
    company: j.companyName, title: j.title, url: j.guid, text: j.description,
    location: (j.locationRestrictions || []).join(', ') }));     // empty: no country limit listed
  for (const j of jobs) {
    if (!j.title || !j.url) continue;
    const text = clean(j.text);
    out.push({ json: {
      company: (j.company || '').trim(), title: j.title.trim(), location: j.location, remote: true, url: j.url,
      source, via: source,                                      // shown on the card as the attribution link
      description_snippet: text.slice(0, 280),
      description: text.slice(0, 3500),
      key: `${norm(j.company)}|${norm(j.title)}`,
    } });
  }
});
return out;
